Sampling Theory



Each student asks 500 people how much they enjoy the Netflix Original Dark.
How many people did each of you ask?

\(30 \times 500 = 15,000\)





Code
library(dplyr)
library(tibble)
library(gt)
library(latex2exp)
# 30 Students in the class
n = 30

# Each student asks 500 people
full_sample = n*500

# Simulate Results
replicate(n = 30,
            rnorm(500,5,7)) |&gt; round(0) |&gt; 
  data.frame() |&gt; 
  rename_with(.fn = function(x) paste0("S", 1:30)) |&gt; 
  summarize_all(mean) |&gt;
  tidyr::pivot_longer(cols = everything(),
                      names_to = "Sample",
                      values_to = "Sample Mean") |&gt; 
  gt() |&gt; 
  tab_options(
    table.width = pct(60),
    table.font.size = 30,
    ) |&gt; 
  opt_row_striping() |&gt; 
  opt_interactive()

Lab 3
Top 100 Billboard Hits



This week we are exploring the Billboard Hot 100 Number Ones Database. This workbook contains substantial data about every song to ever top the Billboard Hot 100 between August 4, 1958 and January 11, 2025. It was compiled by Chris Dalla Riva as he wrote the book Uncharted Territory: What Numbers Tell Us about the Biggest Hit Songs and Ourselves.



library(gt)
library(dplyr)

# Read data file from CSV
billboard &lt;- readr::read_csv('https://raw.githubusercontent.com/rfordatascience/tidytuesday/main/data/2025/2025-08-26/billboard.csv')

billboard |&gt; 
  names() |&gt; 
  data.frame(column_names = _) |&gt; 
  gt() |&gt; 
  cols_width(everything() ~ px(130)) |&gt; 
  opt_row_striping() |&gt; 
  opt_interactive()

Understanding Main Effects
2x2 Table




Code
library(tibble)
library(dplyr)
library(gt)

library(tibble)
library(gt)

# Create a 2x2 factorial table (wide layout)
design_tbl &lt;- tribble(
  ~Condition,     ~`Coffee`, ~`No Coffee`,
  "TV",               3,           4,
  "No TV",            4,           8
)

# Display as a 2x2 factorial grid
design_tbl |&gt;
  gt() |&gt;
  tab_header(
    title = md("**2 × 2 Factorial Design: Coffee × TV**"),
    subtitle = "Mean Happiness Scores by Condition"
  ) |&gt;
  cols_label(
    Condition = "Watched TV?",
    `Coffee` = "Coffee",
    `No Coffee` = "No Coffee"
  ) |&gt;
  fmt_number(
    columns = c(`Coffee`, `No Coffee`),
    decimals = 1
  ) |&gt;
  tab_style(
    style = cell_text(weight = "bold"),
    locations = cells_column_labels()
  ) |&gt;
  tab_style(
    style = cell_fill(color = "#f8f9fa"),
    locations = cells_body(columns = everything())
  ) |&gt;
  tab_spanner(
    label = md("**Coffee Condition**"),
    columns = c(`Coffee`, `No Coffee`)
  ) |&gt;
  tab_footnote(
    footnote = "Higher numbers indicate greater happiness."
  ) |&gt; 
  tab_options(
    table.font.size = 30
  )













