Paired Samples t-Test
Construct the Formula (Computationally)


Code
library(tidyr)
ddata &lt;- 
  data |&gt; 
  mutate(
    id = rep(paste0("p_",1:30),2),
    group = factor(group),
    group = ifelse(group=="Time One", "Time_One","Time_Two")
    ) |&gt; 
  pivot_wider(
    id_cols = "id",
    names_from = "group",
    values_from = "score"
    )


with(ddata, t.test(Time_One,Time_Two,paired = TRUE)) |&gt; 
  tidy() |&gt; 
  rename(
    d = estimate,
    t = statistic, 
    p = p.value,
    df = parameter) |&gt; 
  mutate(
    `CI[ll,uu]` = paste0("[",conf.low |&gt; round(2),", ",conf.high |&gt; round(2),"]"),
    p = ifelse(p &lt;.01, "&lt;.001",p) 
      ) |&gt; 
  select(-conf.low:-alternative) |&gt; 
  select(d,t,df,p,`CI[ll,uu]`) |&gt; 
  gt() |&gt; 
  fmt_auto() |&gt; 
  opt_row_striping() |&gt;   
  tab_options(
    table.font.size = 32,
    table.width = pct(70)
    ) |&gt; 
  tab_style(
    style = cell_text(weight = "bold"),
    locations = cells_column_labels()
  )








